<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import Icon from './Icon.vue';
type Session={account:{id:string;email:string;displayName:string;mustChangePassword:boolean};tenant:{code:string;name:string;brandName:string;supportEmail:string};csrfToken:string;expiresAt:string};
const session=ref<Session|null>(null),busy=ref(false),error=ref(''),notice=ref(''),section=ref('summary'),items=ref<any[]>([]),selected=ref<any|null>(null),summary=ref<any|null>(null),ticketTypes=ref<any[]>([]);
const credentials=reactive({tenantCode:'test-1',email:'',password:''});const passwords=reactive({oldPassword:'',newPassword:'',confirm:''});
const ticket=reactive({title:'',description:'',priority:'NORMAL',typeCode:'GENERAL'});const newTicket=ref(false),reply=ref('');
const brand=computed(()=>session.value?.tenant.brandName||session.value?.tenant.name||'客户服务门户');
async function api<T>(path:string,method='GET',body?:unknown,headers:Record<string,string>={}):Promise<T>{const r=await fetch('/api/v1/portal'+path,{method,credentials:'same-origin',headers:{...(body===undefined||body instanceof FormData?{}:{'Content-Type':'application/json'}),...(session.value?{'X-CSRF-Token':session.value.csrfToken}:{}),...headers},...(body===undefined?{}:{body:body instanceof FormData?body:JSON.stringify(body)})});const value=r.status===204?null:await r.json().catch(()=>({message:'门户服务暂未就绪'}));if(!r.ok){if(r.status===401)session.value=null;throw new Error(value?.message||'操作未完成');}return value as T;}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
async function login(){await run(async()=>{session.value=await api<Session>('/auth/login','POST',credentials);credentials.password='';if(!session.value.account.mustChangePassword)await navigate('summary');});}
async function logout(){await run(async()=>{await api('/auth/logout','POST');session.value=null;items.value=[];selected.value=null;});}
async function changePassword(){await run(async()=>{if(passwords.newPassword!==passwords.confirm)throw new Error('两次输入的新密码不一致');await api('/auth/password','POST',{oldPassword:passwords.oldPassword,newPassword:passwords.newPassword});session.value=null;Object.assign(passwords,{oldPassword:'',newPassword:'',confirm:''});notice.value='密码已修改，请重新登录';});}
async function navigate(next:string){section.value=next;selected.value=null;items.value=[];if(next==='summary'){summary.value=await api('/summary');return;}const path=next==='knowledge'?'/knowledge?pageSize=50':`/${next}?pageSize=50`;const data:any=await api(path);items.value=data.items??data;}
async function open(row:any){await run(async()=>{selected.value=await api(section.value==='knowledge'?'/knowledge/'+row.id:`/${section.value}/${row.id}`);});}
async function createTicket(){await run(async()=>{selected.value=await api('/tickets','POST',ticket,{'Idempotency-Key':crypto.randomUUID()});newTicket.value=false;notice.value='工单已提交，服务人员会在 SLA 时限内处理';await navigate('tickets');selected.value=await api('/tickets/'+selected.value.id);});}
async function prepareTicket(){await run(async()=>{const data:any=await api('/dictionaries');ticketTypes.value=data.ticketTypes??[];ticket.typeCode=ticketTypes.value[0]?.itemCode??'GENERAL';newTicket.value=true;});}
async function sendReply(){if(!selected.value||!reply.value.trim())return;await run(async()=>{selected.value=await api(`/tickets/${selected.value.id}/comments`,'POST',{expectedVersion:selected.value.version,body:reply.value},{'Idempotency-Key':crypto.randomUUID()});reply.value='';notice.value='回复已发送';});}
async function upload(event:Event){if(!selected.value)return;const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await run(async()=>{const form=new FormData();form.append('file',file);await api(`/tickets/${selected.value.id}/attachments`,'POST',form,{'Idempotency-Key':crypto.randomUUID()});selected.value=await api('/tickets/'+selected.value.id);notice.value='附件已上传';});}
async function download(path:string,name:string){const r=await fetch('/api/v1/portal'+path,{credentials:'same-origin'});if(!r.ok)throw new Error('下载未完成');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function money(value:any){return `¥ ${(Number(value||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;}
function label(value:string){return ({APPROVED:'已批准',SIGNED:'已签订',ACTIVE:'履行中',TERMINATED:'已终止',CONFIRMED:'已确认',REVERSED:'已冲正',NEW:'新建',IN_PROGRESS:'处理中',WAITING_CUSTOMER:'等待客户',RESOLVED:'已解决',CLOSED:'已关闭',CANCELLED:'已取消'} as any)[value]??value;}
onMounted(async()=>{try{session.value=await api<Session>('/auth/session');if(!session.value.account.mustChangePassword)await navigate('summary');}catch{session.value=null;}});
</script>

<template>
 <div class="portal-shell"><header><a class="portal-brand" href="?portal=1"><span class="portal-mark"><Icon name="layers" :size="22"/></span><span><strong>{{brand}}</strong><small>客户服务门户</small></span></a><div v-if="session" class="portal-user"><span>{{session.account.displayName}}</span><button class="text-button" @click="logout">退出</button></div><a v-else class="text-button" href="?mode=live">返回企业 CRM</a></header>
  <main>
   <div v-if="error" class="portal-alert bad">{{error}}</div><div v-if="notice" class="portal-alert ok">{{notice}}</div>
   <section v-if="!session" class="portal-login"><div><span class="eyebrow">CUSTOMER PORTAL · P4-B</span><h1>把服务进度，<br/>交还给客户掌握。</h1><p>查看已批准报价、已签合同和确认回款；提交工单、公开回复并跟踪 SLA。客户门户与企业员工 CRM 完全隔离。</p></div><form class="portal-card" @submit.prevent="login"><h2>登录客户门户</h2><label>企业代码<input v-model="credentials.tenantCode" required maxlength="40" autocomplete="organization"/></label><label>登录邮箱<input v-model="credentials.email" type="email" required maxlength="254" autocomplete="username"/></label><label>密码<input v-model="credentials.password" type="password" required maxlength="72" autocomplete="current-password"/></label><button class="btn primary full" :disabled="busy">{{busy?'正在验证…':'进入门户'}}</button><small>账号由服务企业管理员开通，不支持自助注册。</small></form></section>
   <section v-else-if="session.account.mustChangePassword" class="portal-card portal-password"><span class="eyebrow">FIRST SIGN IN</span><h2>首次登录，请设置自己的密码</h2><p>保存后旧会话立即失效，请使用新密码重新登录。</p><form @submit.prevent="changePassword"><label>初始密码<input v-model="passwords.oldPassword" type="password" required maxlength="72"/></label><label>新密码<input v-model="passwords.newPassword" type="password" minlength="12" maxlength="72" required/></label><label>再次输入<input v-model="passwords.confirm" type="password" minlength="12" maxlength="72" required/></label><button class="btn primary" :disabled="busy">保存新密码</button></form></section>
   <template v-else>
    <nav aria-label="客户门户导航"><button v-for="n in [{id:'summary',name:'概览'},{id:'quotes',name:'报价'},{id:'contracts',name:'合同'},{id:'receipts',name:'回款'},{id:'tickets',name:'服务工单'},{id:'knowledge',name:'知识库'}]" :key="n.id" :class="{active:section===n.id}" @click="run(()=>navigate(n.id))">{{n.name}}</button></nav>
    <section v-if="section==='summary'&&summary" class="portal-summary"><div class="portal-heading"><span class="eyebrow">CUSTOMER WORKSPACE</span><h1>{{summary.customer.name}}</h1><p>{{summary.customer.industry}} · {{summary.customer.region||'地区未填写'}} · 客户等级 {{summary.customer.levelCode}}</p></div><div class="portal-metrics"><button @click="run(()=>navigate('quotes'))"><strong>{{summary.counts.quotes}}</strong><span>已批准报价</span></button><button @click="run(()=>navigate('contracts'))"><strong>{{summary.counts.contracts}}</strong><span>履约合同</span></button><button @click="run(()=>navigate('receipts'))"><strong>{{summary.counts.receipts}}</strong><span>确认回款</span></button><button @click="run(()=>navigate('tickets'))"><strong>{{summary.counts.tickets}}</strong><span>服务工单</span></button></div><section class="portal-card portal-guide"><h2>这里能做什么</h2><p>业务单据只展示与当前客户绑定、且已进入对外状态的记录；工单只显示公开回复。内部备注、审批明细和其他客户资料不会进入门户。</p><p v-if="session.tenant.supportEmail">需要协助：{{session.tenant.supportEmail}}</p></section></section>
    <template v-else>
     <div class="portal-heading"><div><span class="eyebrow">{{section.toUpperCase()}}</span><h1>{{section==='quotes'?'报价':section==='contracts'?'合同':section==='receipts'?'回款':section==='tickets'?'服务工单':'知识库'}}</h1></div><button v-if="section==='tickets'" class="btn primary" @click="prepareTicket">提交工单</button></div>
     <section class="portal-card portal-list"><div v-for="row in items" :key="row.id" class="portal-row"><div><strong>{{row.quoteNumber||row.contractNumber||row.receiptNumber||row.ticketNumber||row.title}}</strong><span>{{row.title||row.contractNumberSnapshot||row.category||''}}</span></div><span v-if="row.totalCents||row.amountCents" class="portal-money">{{money(row.totalCents||row.amountCents)}}</span><span v-if="row.status" class="badge neutral">{{label(row.status)}}</span><button class="text-button" @click="open(row)">查看</button></div><p v-if="!items.length" class="portal-empty">暂无可查看记录</p></section>
     <section v-if="selected" class="portal-card portal-detail"><div class="portal-detail-head"><div><span class="eyebrow">DETAIL</span><h2>{{selected.quoteNumber||selected.contractNumber||selected.receiptNumber||selected.ticketNumber||selected.title}}</h2></div><button class="text-button" @click="selected=null">关闭</button></div><p v-if="selected.description||selected.body||selected.notes" class="portal-copy">{{selected.description||selected.body||selected.notes}}</p><dl><template v-for="(value,key) in selected" :key="String(key)"><template v-if="!['description','body','notes','comments','attachments','lines','plans','sla'].includes(String(key))&&typeof value!=='object'"><dt>{{key}}</dt><dd>{{String(key).endsWith('Cents')?money(value):value??'—'}}</dd></template></template></dl><div v-if="section==='quotes'" class="portal-actions"><button class="btn secondary" @click="download(`/quotes/${selected.id}/pdf`,`${selected.quoteNumber}.pdf`)">下载 PDF</button></div><div v-if="selected.lines?.length" class="portal-sub"><h3>报价明细</h3><div v-for="line in selected.lines" :key="line.lineNumber" class="portal-subrow"><span>{{line.nameSnapshot}} × {{line.quantity}}</span><strong>{{money(line.amountCents)}}</strong></div></div><div v-if="selected.plans?.length" class="portal-sub"><h3>收款计划</h3><div v-for="plan in selected.plans" :key="plan.id" class="portal-subrow"><span>{{plan.title}} · {{plan.dueDate}}</span><strong>{{money(plan.amountCents)}}</strong></div></div><template v-if="section==='tickets'"><div v-if="selected.sla" class="portal-sla"><strong>SLA 进度</strong><span>首次响应截止 {{selected.sla.firstResponseDueAt?new Date(selected.sla.firstResponseDueAt).toLocaleString():'—'}}</span><span>解决截止 {{selected.sla.resolutionDueAt?new Date(selected.sla.resolutionDueAt).toLocaleString():'—'}}</span></div><div class="portal-sub"><h3>公开沟通</h3><div v-for="c in selected.comments" :key="c.id" class="portal-comment" :class="{customer:c.customerReply}"><strong>{{c.actorNameSnapshot}}</strong><span>{{new Date(c.createdAt).toLocaleString()}}</span><p>{{c.body}}</p></div><form v-if="['NEW','IN_PROGRESS','WAITING_CUSTOMER'].includes(selected.status)" @submit.prevent="sendReply"><textarea v-model="reply" required rows="4" maxlength="4000" placeholder="补充信息或回复服务人员"></textarea><button class="btn primary" :disabled="busy">发送公开回复</button></form></div><div class="portal-sub"><h3>附件</h3><button v-for="f in selected.attachments" :key="f.id" class="portal-file" @click="download('/attachments/'+f.id,f.fileName)">{{f.fileName}} · {{Math.ceil(f.sizeBytes/1024)}} KB</button><label v-if="['NEW','IN_PROGRESS','WAITING_CUSTOMER'].includes(selected.status)" class="portal-upload">上传附件（PNG/JPEG/PDF/TXT/CSV，最大 5MB）<input type="file" accept=".png,.jpg,.jpeg,.pdf,.txt,.csv" @change="upload"/></label></div></template></section>
    </template>
   </template>
  </main>
  <div v-if="newTicket" class="modal-backdrop" @click.self="newTicket=false"><form class="portal-card portal-ticket" @submit.prevent="createTicket"><div class="portal-detail-head"><h2>提交服务工单</h2><button type="button" class="text-button" @click="newTicket=false">关闭</button></div><label>主题<input v-model="ticket.title" required maxlength="200"/></label><div class="portal-two"><label>类型<select v-model="ticket.typeCode"><option v-for="t in ticketTypes" :key="t.itemCode" :value="t.itemCode">{{t.label}}</option></select></label><label>优先级<select v-model="ticket.priority"><option value="URGENT">紧急</option><option value="HIGH">高</option><option value="NORMAL">普通</option><option value="LOW">低</option></select></label></div><label>问题说明<textarea v-model="ticket.description" rows="8" maxlength="10000"></textarea></label><button class="btn primary" :disabled="busy">提交工单</button></form></div>
 </div>
</template>

<style scoped>
.portal-shell{min-height:100vh;background:#f4f7f5;color:#19372a}.portal-shell header{height:82px;padding:0 5%;background:#fff;border-bottom:1px solid #dce5df;display:flex;align-items:center;justify-content:space-between}.portal-brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.portal-brand>span:last-child{display:flex;flex-direction:column}.portal-brand small{font-size:11px;color:#718078;margin-top:3px}.portal-mark{width:39px;height:39px;border-radius:11px;background:#285f42;color:#fff;display:grid;place-items:center}.portal-user{display:flex;align-items:center;gap:18px;font-size:13px}.portal-shell main{max-width:1160px;margin:auto;padding:38px 28px}.portal-login{min-height:68vh;display:grid;grid-template-columns:1.3fr 420px;gap:90px;align-items:center}.portal-login h1{font-size:48px;line-height:1.25;margin:18px 0}.portal-login>div>p{max-width:620px;line-height:1.9;color:#5c6d62}.portal-card{background:#fff;border:1px solid #dce5df;border-radius:14px;box-shadow:0 14px 45px #214c3308}.portal-login form,.portal-password,.portal-ticket{padding:34px}.portal-card label{display:flex;flex-direction:column;gap:8px;margin:17px 0;font-size:13px}.portal-card input,.portal-card select,.portal-card textarea{padding:12px;border:1px solid #cbd7cf;border-radius:7px;background:#fff}.portal-card small{display:block;color:#6d7b72;font-size:12px;line-height:1.7;margin-top:17px}.portal-password{max-width:540px;margin:40px auto}.portal-shell nav{display:flex;gap:8px;flex-wrap:wrap;background:#fff;border:1px solid #dce5df;border-radius:11px;padding:10px;margin-bottom:30px}.portal-shell nav button{padding:11px 16px;border:0;background:transparent;border-radius:7px;color:#4c6254}.portal-shell nav button.active{background:#dfeee4;color:#205f39;font-weight:600}.portal-heading{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:18px 0 25px}.portal-heading h1{font-size:34px;margin:8px 0}.portal-heading p{color:#69786e}.portal-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.portal-metrics button{background:#fff;border:1px solid #dce5df;border-radius:12px;padding:24px;text-align:left}.portal-metrics strong{display:block;font-size:32px;color:#265e40}.portal-metrics span{display:block;font-size:12px;color:#6a7a70;margin-top:7px}.portal-guide{padding:25px;margin-top:20px}.portal-guide p{line-height:1.8;color:#5f7065}.portal-list{overflow:hidden}.portal-row{display:grid;grid-template-columns:minmax(260px,1fr) 150px 100px 70px;align-items:center;gap:16px;padding:18px 22px;border-bottom:1px solid #e6ece8}.portal-row>div{display:flex;flex-direction:column;gap:5px}.portal-row span{font-size:12px;color:#6b796f}.portal-money{font-size:14px!important;color:#264f39!important;font-weight:600}.portal-empty{text-align:center;padding:50px;color:#708078}.portal-detail{margin-top:20px;padding:24px}.portal-detail-head{display:flex;align-items:center;justify-content:space-between;gap:16px}.portal-detail h2{margin:7px 0}.portal-copy{white-space:pre-wrap;line-height:1.85;color:#4f6256}.portal-detail dl{display:grid;grid-template-columns:180px 1fr;margin:20px 0}.portal-detail dt,.portal-detail dd{padding:9px;border-bottom:1px solid #e6ece8;font-size:13px}.portal-detail dt{color:#6b796f}.portal-actions{display:flex;gap:10px}.portal-sub{border-top:1px solid #e1e8e3;padding-top:19px;margin-top:20px}.portal-subrow{display:flex;justify-content:space-between;gap:15px;padding:11px 0;border-bottom:1px solid #edf1ee;font-size:13px}.portal-sla{display:flex;flex-wrap:wrap;gap:14px;padding:15px;background:#edf5ef;border-radius:8px;font-size:12px}.portal-comment{padding:14px;background:#f4f7f5;border-radius:9px;margin:9px 0}.portal-comment.customer{background:#e9f2ec;margin-left:8%}.portal-comment span{font-size:11px;color:#75827a;margin-left:10px}.portal-comment p{margin:8px 0 0;white-space:pre-wrap;line-height:1.7}.portal-sub form textarea{width:100%;box-sizing:border-box}.portal-file{display:block;border:0;background:none;color:#226544;padding:7px 0;cursor:pointer}.portal-upload{padding:13px;background:#f6f8f7;border-radius:8px}.portal-two{display:grid;grid-template-columns:1fr 1fr;gap:16px}.portal-ticket{width:min(620px,calc(100vw - 30px));max-height:calc(100dvh - 40px);overflow:auto}.portal-alert{padding:13px 16px;border-radius:8px;margin-bottom:16px;font-size:13px}.portal-alert.bad{background:#fff0f1;color:#9d2433}.portal-alert.ok{background:#eaf5ed;color:#286045}@media(max-width:800px){.portal-login{grid-template-columns:1fr;gap:30px}.portal-login h1{font-size:36px}.portal-metrics{grid-template-columns:1fr 1fr}.portal-row{grid-template-columns:1fr auto}.portal-row .portal-money{display:none}.portal-detail dl{grid-template-columns:1fr}.portal-detail dt{border-bottom:0;padding-bottom:0}}@media(max-width:480px){.portal-shell main{padding:25px 16px}.portal-metrics{grid-template-columns:1fr}.portal-two{grid-template-columns:1fr}.portal-login form{padding:25px}}
</style>
